Given an array arr[], the task is to determine the maximum possible value of the expression i*arr[i] after rotating the array any number of times (including zero).Note: In each rotation, every element of the array shifts one position to the right, and the last element moves to the front.Examples :  Input: arr[] = [4, 3, 2, 6, 1, 5]Output: 60Explanation: After rotating the array 3 times, we get [1, 5, 4, 3, 2, 6]. Now, the sum of i*arr[i] = 0*1 + 1*5 + 2*4 + 3*3 + 4*2 + 5*6 = 0 + 5 + 8 + 9 + 8 + 30 = 60Input: arr[] = [8, 3, 1, 2]Output: 29Explanation: After rotating the array 3 times, we get [3, 1, 2, 8]. Now, the sum of i*arr[i] = 0*3 + 1*1 + 2*2 + 3*8 = 0 + 1 + 4 + 24 = 29.Input: arr[] = [10, 1, 2, 7, 9, 3]Output: 105Table of Content[Naive Approach] Take Maximum of All Rotations - O(n^2) Time and O(1) Space [Expected Approach] Using Mathematical Formula   - O(n) Time and O(1) Space[Naive Approach] Take Maximum of All Rotations - O(n^2) Time and O(1) Space The idea is to check all possible rotations of the array. As on each rotation, the value of the expression changes as the index positions shift. We rotate the array one step at a time and compute the new sum. By tracking the maximum of these sum values, we ensure we capture the best possible configuration.
            C++

    // C++ Code to find maximum value of Sum of 
// i*arr[i] with rotations using Naive Approach
#include <iostream>
#include <vector>
#include <climits>
using namespace std;

// Function to calculate i*arr[i]
// for given array
int computeSum(vector<int> &arr) {

    int n = arr.size();
    int total = 0;

    // Calculate the sum of i*arr[i]
    for (int i = 0; i < n; i++) {
        total += i * arr[i];
    }

    return total;
}

// Function to find maximum value of i*arr[i]
// after any number of rotations
int maxRotateSum(vector<int> &arr) {

    int n = arr.size();

    int maxVal = INT_MIN;

    // Try all rotations
    for (int r = 0; r < n; r++) {

        // Calculate i*arr[i] for 
        // current rotation
        int currVal = computeSum(arr);

        // Update max value
        maxVal = max(maxVal, currVal);

        // Rotate array by 1 to right
        int last = arr[n - 1];
        for (int i = n - 1; i > 0; i--) {
            arr[i] = arr[i - 1];
        }
        arr[0] = last;
    }

    return maxVal;
}

// Driver code
int main() {

    vector<int> arr = {4, 3, 2, 6, 1, 5};
    cout << maxRotateSum(arr);

    return 0;
}


